def correlations(subset, family):
    rows = []
    for c in cell_features:
        for p in protein_features:
            z = subset[[c, p]].dropna()
            if len(z) >= 5 and z[c].nunique() >= 2 and z[p].nunique() >= 2:
                rho, pv = spearmanr(z[c], z[p])
                rows.append({"cell": c, "protein": p, "n": len(z),
                             "rho": rho, "p": pv})
    out = pd.DataFrame(rows)
    out["q"] = multipletests(out["p"], method="fdr_bh")[1]
    out["family"] = family
    return out.sort_values(["q", "p"])

